namespace Juwri\Modules\Storefront\Services\Theme;

/**
 * Phase 3 (P3-00) — the five Community kit themes (table, brew, aisle, basket, book).
 *
 * `SchemaV2::normalize` drops unknown top-level keys, so a theme file cannot mark
 * itself as a kit theme: the slugs are registered here, next to KeptTemplates.
 *
 * Their theme.json and css/tokens.css under assets/store_templates/<slug>/ are
 * GENERATED by tools/themes/tools/build_theme_json.py and build_theme_css.py from
 * tools/themes/tokens/<slug>.json. Never hand-edit them; regenerate.
 *
 * Importing the assets does not switch any store to these themes; the Blade
 * views arrive with P3-05 and later.
 */
final class KitThemes
{
    /** @var list<string> */
    public const SLUGS = ['table', 'brew', 'aisle', 'basket', 'book'];

    /**
     * P3-02: the kit theme a store type renders with (the view model's theme when the store's own template is not
     * a kit theme yet): food -> table (cafe -> brew), goods -> aisle (grocery -> basket), services -> book.
     */
    public const FOR_TYPE = [
        'restaurant' => 'table', 'hotel' => 'table', 'cafe' => 'brew',
        'retail' => 'aisle', 'cosmetic' => 'aisle', 'clothing' => 'aisle', 'carparts' => 'aisle', 'pharmacy' => 'aisle',
        'grocery' => 'basket',
        'services' => 'book', 'laundry' => 'book',
    ];

    public static function isKit(?string $template): bool
    {
        return in_array((string) $template, self::SLUGS, true);
    }

    /** The kit theme for a store type (an unknown type renders with the reference theme `table`). */
    public static function forStoreType(?string $type): string
    {
        return self::FOR_TYPE[(string) $type] ?? 'table';
    }
}
